<?php require_once __DIR__.'/../config/conexao.php';verificarAcesso('entregador');$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){validarCsrf();$id=(int)$_POST['pedido'];$act=$_POST['acao'];if($act==='assumir'){$q=db()->prepare("UPDATE pedidos SET id_entregador=?,status='em_transito' WHERE id_pedido=? AND status='pronto' AND id_entregador IS NULL");$q->execute([$_SESSION['usuario']['id_usuario'],$id]);$msg=$q->rowCount()?'Pedido assumido.':'Este pedido já foi assumido.';}elseif($act==='entregar'){$q=db()->prepare("UPDATE pedidos SET status='entregue' WHERE id_pedido=? AND id_entregador=? AND status='em_transito' AND pin_entrega=?");$q->execute([$id,$_SESSION['usuario']['id_usuario'],$_POST['pin']??'']);$msg=$q->rowCount()?'Entrega confirmada.':'PIN incorreto ou pedido indisponível.';}elseif($act==='problema'){$q=db()->prepare("UPDATE pedidos SET status='problema',observacao_problema=? WHERE id_pedido=? AND id_entregador=? AND status='em_transito'");$q->execute([trim($_POST['motivo']??''),$id,$_SESSION['usuario']['id_usuario']]);$msg=$q->rowCount()?'Ocorrência registrada.':'Não foi possível registrar a ocorrência.';}}$q=db()->prepare("SELECT p.*,e.logradouro,e.numero,e.bairro,e.cidade,e.cep,u.nome cliente,u.telefone FROM pedidos p JOIN enderecos e USING(id_endereco) JOIN usuarios u ON u.id_usuario=p.id_cliente WHERE p.modalidade_entrega<>'retirada' AND (p.status='pronto' OR (p.status='em_transito' AND p.id_entregador=?)) ORDER BY p.data_criacao");$q->execute([$_SESSION['usuario']['id_usuario']]);$orders=$q->fetchAll();?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Entregas · Alvorada</title><link rel="stylesheet" href="/assets/css/style.css"></head><body><main class="container"><h1>Painel do entregador</h1><?php if($msg):?><div class="notice"><?=h($msg)?></div><?php endif;?><?php foreach($orders as $o):?><section class="card"><h2>Pedido #<?=$o['id_pedido']?> <span class="status"><?=h($o['status'])?></span></h2><p><strong><?=h($o['cliente'])?></strong> · <?=h($o['telefone'])?><br><?=h($o['logradouro'].' '.$o['numero'].', '.$o['bairro'].', '.$o['cidade'].' '.$o['cep'])?></p><a class="button light" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&amp;query=<?=rawurlencode($o['logradouro'].' '.$o['numero'].' '.$o['cidade'].' '.$o['cep'])?>">Abrir rota</a><?php if($o['status']==='pronto'):?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="pedido" value="<?=$o['id_pedido']?>"><input type="hidden" name="acao" value="assumir"><button>Assumir entrega</button></form><?php else:?><form method="post" class="form"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="pedido" value="<?=$o['id_pedido']?>"><input type="hidden" name="acao" value="entregar"><label>PIN de 6 dígitos<input name="pin" inputmode="numeric" pattern="\d{6}" maxlength="6" required></label><button>Confirmar entrega</button></form><details><summary>Registrar problema</summary><form method="post" class="form"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="pedido" value="<?=$o['id_pedido']?>"><input type="hidden" name="acao" value="problema"><label>Motivo<textarea name="motivo" required></textarea></label><button class="button secondary">Registrar ocorrência</button></form></details><?php endif;?></section><?php endforeach;?><?php if(!$orders):?><div class="card">Não há entregas disponíveis no momento.</div><?php endif;?></main></body></html>
